/**
 * Writes scripts/init-db.sql: every migration plus the matching drizzle journal rows, for
 * creating the schema by hand on an empty database (e.g. from Railway's query console).
 * Run after `npm run db:generate`:  npm run db:init-sql
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';

const journal = JSON.parse(readFileSync('drizzle/meta/_journal.json', 'utf8')) as {
  entries: { tag: string; when: number }[];
};

let out =
  '-- JobBuddy: create every table by hand (EMPTY database only). Generated by\n' +
  '-- scripts/generate-init-sql.ts. Also records the migrations in the drizzle journal so the\n' +
  "-- app's own migrate step on startup knows they're already applied.\nBEGIN;\n\n";
const rows: string[] = [];
for (const e of journal.entries) {
  const query = readFileSync(`drizzle/${e.tag}.sql`, 'utf8');
  // Same hash drizzle's migrator computes for each file.
  const hash = createHash('sha256').update(query).digest('hex');
  const statements = query
    .split('--> statement-breakpoint')
    .map((s) => s.trim())
    .filter(Boolean);
  out += `-- ${e.tag}\n${statements.map((s) => (s.endsWith(';') ? s : `${s};`)).join('\n')}\n\n`;
  rows.push(`('${hash}', ${e.when})`);
}
out +=
  'CREATE SCHEMA IF NOT EXISTS drizzle;\n' +
  'CREATE TABLE IF NOT EXISTS drizzle.__drizzle_migrations (\n' +
  '  id SERIAL PRIMARY KEY,\n  hash text NOT NULL,\n  created_at bigint\n);\n' +
  `INSERT INTO drizzle.__drizzle_migrations (hash, created_at) VALUES\n  ${rows.join(',\n  ')};\n\n` +
  'COMMIT;\n';
writeFileSync('scripts/init-db.sql', out);
console.log(`Wrote scripts/init-db.sql (${journal.entries.length} migrations)`);
